    /**
    * Calls:
    * 1 - (201) POST:/petclinic/api/owners
    * 2 - (404) POST:/petclinic/api/owners/{ownerId}/pets
    * Using 6 examples:
    *   (-) BODY -> 1
    *   (-) BODY -> 6085551023
    *   (-) BODY -> Franklin
    *   (-) BODY -> George
    *   (-) BODY -> Leo
    *   (-) BODY -> cat
    */
    @Test @Timeout(60)
    public void test_35_postOnPetsReturns404() throws Exception {
        
        ValidatableResponse res_0 = given().accept("application/json")
                .contentType("application/json")
                .body(" { " + 
                    " \"firstName\" : \"George\", " + 
                    " \"lastName\" : \"Franklin\", " + 
                    " \"address\" : \"jV\", " + 
                    " \"city\" : \"i45xAZNQK2jDKC\", " + 
                    " \"telephone\" : \"6085551023\" " + 
                    " } ")
                .post(baseUrlOfSut + "/petclinic/api/owners")
                .then()
                .statusCode(201)
                .assertThat()
                .contentType("application/json")
                .body("'firstName'", containsString("George"))
                .body("'lastName'", containsString("Franklin"))
                .body("'address'", containsString("jV"))
                .body("'city'", containsString("i45xAZNQK2jDKC"))
                .body("'telephone'", containsString("6085551023"))
                .body("'pets'.size()", equalTo(0));
        String location_owners__2 = res_0.extract().header("location");
        assertTrue(isValidURIorEmpty(location_owners__2));
        
        given().accept("*/*")
                .contentType("application/json")
                .body(" { " + 
                    " \"name\" : \"Leo\", " + 
                    " \"birthDate\" : \"2078-04-29\", " + 
                    " \"type\" : { " + 
                    " \"name\" : \"cat\", " + 
                    " \"id\" : 1 " + 
                    " } " + 
                    " } ")
                .post(resolveLocation(location_owners__2, baseUrlOfSut + "/petclinic/api/owners/710/pets"))
                .then()
                .statusCode(404)
                .assertThat()
                .contentType("text/html");
        
        // Cleanup actions
        given().accept("*/*")
                .delete(resolveLocation(location_owners__2, baseUrlOfSut + "/petclinic/api/owners/75"))
                .then()
                .statusCode(404)
                .assertThat()
                .contentType("text/html");
    }
    
    
